/**
 * Colour maps of the workshop, written once from utils/maps.py of the presentation (Part A) through
 * its export_json (data/colormaps.json, generated by manim/tools/make_web_fixtures.py). T uses viridis,
 * f_s a grey ramp with more soot as more ink (black to white on the dark theme, white to black on the
 * light one), j_j a ramp from the background to the fixed channel colour, errors a PuOr diverging map.
 * Never a rainbow or a fire palette. Same lookup as maps.py, index round((v − vmin)/(vmax − vmin)·255)
 * with Python's round half to even, values outside clipped.
 */
import maps from './data/colormaps.json' with { type: 'json' };
import { roundHalfEven } from './stats.ts';

export type Theme = 'dark' | 'light';
export type MapName = 't' | 'fs' | 'ch_R' | 'ch_G' | 'ch_B' | 'div';
export const N = 256;

type Tables = Record<string, string[] | string>;
const T = maps as unknown as Tables;

/** The site's light theme is the presentation's sala theme. */
const themeKey = (theme: Theme) => (theme === 'light' ? 'sala' : 'dark');

/** The 256 '#RRGGBB' strings of a map for a theme. */
export function table(name: MapName, theme: Theme = 'dark'): string[] {
  const key = name === 't' ? 't' : name === 'fs' ? `fs_${themeKey(theme)}` : name === 'div' ? `div_${themeKey(theme)}` : `${name}_${themeKey(theme)}`;
  const t = T[key];
  if (!Array.isArray(t) || t.length !== N) throw new Error(`colormap_${key}`);
  return t;
}

export function index(value: number, vmin: number, vmax: number): number {
  let x = vmax === vmin ? 0 : (value - vmin) / (vmax - vmin);
  x = Math.min(Math.max(x, 0), 1);
  return roundHalfEven(x * (N - 1));
}

export function hex(name: MapName, value: number, vmin = 0, vmax = 1, theme: Theme = 'dark'): string {
  return table(name, theme)[index(value, vmin, vmax)];
}

/** Diverging colour of an error on the symmetric scale [−vmax, vmax]. */
export function divHex(value: number, vmax: number, theme: Theme = 'dark'): string {
  return table('div', theme)[index(value, -vmax, vmax)];
}

export function rgb(h: string): [number, number, number] {
  return [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
}

/**
 * RGBA image of a field (row-major), NaN and masked pixels in the page background colour and never
 * as zero (WEB_SPEC §10).
 */
export function colorize(values: ArrayLike<number>, name: MapName, vmin: number, vmax: number, theme: Theme, background: string, mask?: ArrayLike<number> | null): Uint8ClampedArray {
  const tab = table(name, theme).map(rgb), bg = rgb(background);
  const out = new Uint8ClampedArray(values.length * 4);
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    const c = Number.isFinite(v) && (!mask || mask[i]) ? tab[index(v, vmin, vmax)] : bg;
    out[4 * i] = c[0]; out[4 * i + 1] = c[1]; out[4 * i + 2] = c[2]; out[4 * i + 3] = 255;
  }
  return out;
}

/**
 * Filled contours of a field (row-major, ny × nx), as matplotlib's contourf: each value sits at the centre of
 * its cell, the field is linear between neighbours and takes the colour of its band. A square with a NaN or
 * masked corner stays in the page colour, so nothing is drawn beyond the valid points. The image is
 * nx·s × ny·s with s pixels per cell. Values outside [vmin, vmax] take the first or last band.
 */
export function contourf(values: ArrayLike<number>, nx: number, ny: number, s: number, name: MapName, vmin: number, vmax: number, levels: number, theme: Theme, background: string, mask?: ArrayLike<number> | null): Uint8ClampedArray {
  const tab = table(name, theme).map(rgb), bg = rgb(background);
  const band = Array.from({ length: levels }, (_, b) => tab[Math.round(((b + 0.5) / levels) * (N - 1))]);
  const W = nx * s, H = ny * s, out = new Uint8ClampedArray(W * H * 4), span = vmax - vmin;
  const ok = (q: number) => Number.isFinite(values[q]) && (!mask || !!mask[q]);
  for (let py = 0; py < H; py++) {
    const v = (py + 0.5) / s - 0.5, j = Math.floor(v), fy = v - j;
    for (let px = 0; px < W; px++) {
      const u = (px + 0.5) / s - 0.5, i = Math.floor(u), fx = u - i, o = 4 * (py * W + px);
      let c = bg;
      if (i >= 0 && j >= 0 && i + 1 < nx && j + 1 < ny) {
        const a = j * nx + i, b = a + 1, d = a + nx, e = d + 1;
        if (ok(a) && ok(b) && ok(d) && ok(e)) {
          const x = (values[a] * (1 - fx) + values[b] * fx) * (1 - fy) + (values[d] * (1 - fx) + values[e] * fx) * fy;
          c = band[span > 0 ? Math.max(0, Math.min(levels - 1, Math.floor(((x - vmin) / span) * levels))) : 0];
        }
      }
      out[o] = c[0]; out[o + 1] = c[1]; out[o + 2] = c[2]; out[o + 3] = 255;
    }
  }
  return out;
}
